function validate([nums, multipliers]) {
  const n = nums.length, m = multipliers.length;
  if (m < 1 || m > 300) return 'multipliers needs 1 to 300 values.';
  if (n < m) return 'nums must be at least as long as multipliers.';
  if (n > 100000) return 'nums has at most 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -1000 || v > 1000)) return 'Each nums value is an integer between -1000 and 1000.';
  if (multipliers.some(v => !Number.isInteger(v) || v < -1000 || v > 1000)) return 'Each multiplier is an integer between -1000 and 1000.';
  return null;
}

