function maximumScore(nums, multipliers) {
  const n = nums.length;
  const m = multipliers.length;
  const dp = Array.from({ length: m + 1 }, () => new Array(m + 1).fill(0));

  for (let i = m - 1; i >= 0; i--) {
    for (let left = i; left >= 0; left--) {
      const right = n - 1 - (i - left);
      const takeLeft = multipliers[i] * nums[left] + dp[i + 1][left + 1];
      const takeRight = multipliers[i] * nums[right] + dp[i + 1][left];
      dp[i][left] = Math.max(takeLeft, takeRight);
    }
  }
  return dp[0][0];
}

