function maximumScore(nums, multipliers) {
  const explore = (rest, step) => {
    if (step === multipliers.length) return 0;
    const first = multipliers[step] * rest[0] + explore(rest.slice(1), step + 1);
    const last = multipliers[step] * rest[rest.length - 1] + explore(rest.slice(0, -1), step + 1);
    return first > last ? first : last;
  };
  return explore(nums.slice(), 0);
}

