function generate(rand, size) {
  const pick = (span) => Math.floor(rand() * (2 * span + 1)) - span;
  if (size === 'large') {
    const n = 1000 + Math.floor(rand() * 1001);
    const m = 250 + Math.floor(rand() * 51);
    return [Array.from({ length: n }, () => pick(1000)), Array.from({ length: m }, () => pick(1000))];
  }
  const m = 1 + Math.floor(rand() * 7);
  const n = m + Math.floor(rand() * 5);
  const span = rand() < 0.2 ? 1000 : rand() < 0.5 ? 3 : 15;
  return [Array.from({ length: n }, () => pick(span)), Array.from({ length: m }, () => pick(span))];
}
